{
  "story": "The generator crafts synthetic samples to fool the discriminator. The discriminator evaluates real and fake data, driving both to improve iteratively.",
  "aha": {
    "stateId": "step_rivalry",
    "observation": "As the discriminator gets better at catching fakes, the generator adapts to produce indistinguishable samples."
  },
  "layout": {
    "preset": "stepper-compact",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "picture",
      "kind": "fixed-picture",
      "bind": {
        "active": "state.active",
        "regions": "variant.regions",
        "values": "state.readouts"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "readout",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Training Step",
      "options": [
        "1",
        "2",
        "3",
        "4"
      ]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset"
    }
  ],
  "data": {
    "variants": [
      {
        "label": "GAN Training Loop",
        "regions": [
          {
            "id": "reg_gen",
            "label": "Generator",
            "kind": "actor",
            "values": ["noise", "synthetic data"]
          },
          {
            "id": "reg_disc",
            "label": "Discriminator",
            "kind": "actor",
            "values": ["real data", "fake data", "probability"]
          }
        ],
        "links": [
          {
            "from": "reg_gen",
            "to": "reg_disc",
            "label": "feeds fake data"
          }
        ],
        "states": [
          {
            "id": "step_noise",
            "label": "Initialization",
            "short": "Noise Input",
            "sentence": "The generator takes random noise and produces crude fake samples.",
            "why": "Initial synthetic outputs bear no resemblance to real data.",
            "active": ["reg_gen"],
            "calloutRegion": "reg_gen",
            "readouts": [
              {
                "id": "r1",
                "label": "Generator Loss",
                "value": "High"
              },
              {
                "id": "r2",
                "label": "Discriminator Accuracy",
                "value": "50%"
              }
            ]
          },
          {
            "id": "step_eval",
            "label": "Evaluation",
            "short": "Discrimination",
            "sentence": "The discriminator inspects real data and fake samples to classify them.",
            "why": "It easily spots the artifacts in early generator outputs.",
            "active": ["reg_disc"],
            "calloutRegion": "reg_disc",
            "readouts": [
              {
                "id": "r1",
                "label": "Generator Loss",
                "value": "Medium"
              },
              {
                "id": "r2",
                "label": "Discriminator Accuracy",
                "value": "95%"
              }
            ]
          },
          {
            "id": "step_rivalry",
            "label": "Adversary Update",
            "short": "Backpropagation",
            "sentence": "Both networks update weights: discriminator penalizes fakes, generator learns from feedback.",
            "why": "This adversarial feedback loop forces continuous refinement.",
            "active": ["reg_gen", "reg_disc"],
            "calloutRegion": "reg_disc",
            "readouts": [
              {
                "id": "r1",
                "label": "Generator Loss",
                "value": "Decreasing"
              },
              {
                "id": "r2",
                "label": "Discriminator Accuracy",
                "value": "70%"
              }
            ]
          },
          {
            "id": "step_converge",
            "label": "Nash Equilibrium",
            "short": "Equilibrium",
            "sentence": "The generator crafts realistic data, fooling the discriminator half the time.",
            "why": "The discriminator cannot tell real from fake, yielding 50 percent accuracy.",
            "active": ["reg_gen", "reg_disc"],
            "calloutRegion": "reg_gen",
            "readouts": [
              {
                "id": "r1",
                "label": "Generator Loss",
                "value": "Balanced"
              },
              {
                "id": "r2",
                "label": "Discriminator Accuracy",
                "value": "50%"
              }
            ]
          }
        ]
      }
    ]
  }
}
